import React, { ElementType, forwardRef, useRef } from 'react';
import { renderElement, type RenderProp } from '../internal/render';
import { Spark, SparkHandle } from '../Spark';
import { cx } from '../internal/cx';

export interface ButtonBaseProps extends React.ButtonHTMLAttributes<HTMLElement> {
  /** Render as another element or component, e.g. `"a"` or a router Link. */
  as?: ElementType;
  /** Render a different element (e.g. a router link) with the button's behaviour and styling. */
  render?: RenderProp<{ disabled: boolean }>;
  /** Dead circuit: no clicks, no sparks. Uses `disabled` on buttons, `aria-disabled` otherwise. */
  disabled?: boolean;
  /** Throw sparks from the press point on click. Default `true`. */
  spark?: boolean;
  /** Spark colours. Default: the theme's spark colours. */
  sparkColors?: string[];
  /** Link target when rendered as an anchor. */
  href?: string;
  [key: `data-${string}`]: unknown;
}

/**
 * The unstyled foundation of every button. It handles presses, focus rings,
 * disabled states and sparks; you bring the look. Use it to build your own
 * buttons that behave like the rest of Sparkwire.
 *
 * The pressable foundation under Button, IconButton and menu
 * triggers. Handles disabled state for any element, `type="button"` by
 * default, and the spark burst. No visual style of its own beyond
 * `.sp-button-base`; build your own buttons on it.
 */
export const ButtonBase = forwardRef<HTMLElement, ButtonBaseProps>(function ButtonBase(
  { as: Component = 'button', render, disabled = false, spark = true, sparkColors, onClick, className, children, type, ...rest },
  ref,
) {
  const sparkRef = useRef<SparkHandle>(null);
  // A rendered element (link, motion component) is not a native button: no `disabled`/`type`, aria-disabled instead.
  const isButton = Component === 'button' && !render;
  return renderElement(Component, render, {
    ref,
    className: cx('sp-button-base', className),
    'data-disabled': disabled || undefined,
    disabled: isButton ? disabled : undefined,
    'aria-disabled': !isButton && disabled ? true : undefined,
    type: isButton ? type ?? 'button' : type,
    onClick: (event: React.MouseEvent<HTMLElement>) => {
      if (disabled) {
        event.preventDefault();
        return;
      }
      if (spark) sparkRef.current?.burst(event);
      onClick?.(event as React.MouseEvent<HTMLButtonElement>);
    },
    ...rest,
    children: (
      <>
        {children}
        {spark && <Spark ref={sparkRef} colors={sparkColors} />}
      </>
    ),
  }, { disabled });
});

export default ButtonBase;

import React, { forwardRef, useRef } from 'react';
import { mergeRefs } from 'react-aria';
import { slot, ClassNames } from '../internal/defaults';

export interface InputBaseProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'size'> {
  /** `outlined` (default), `filled` or `standard` (underline only). */
  variant?: 'outlined' | 'filled' | 'standard';
  /** Marks the field invalid. */
  error?: boolean;
  /** Turns the control off: it can't be focused or changed, and it's announced as disabled. */
  disabled?: boolean;
  /** Height 36, 46 or 54px. Default `medium`. */
  size?: 'small' | 'medium' | 'large';
  /** Shown before the input, e.g. an icon or a currency sign. */
  startAdornment?: React.ReactNode;
  /** Shown after the input, e.g. a clear button or a chevron. */
  endAdornment?: React.ReactNode;
  /** Props for the outer shell (data attributes, handlers, style). */
  rootProps?: React.HTMLAttributes<HTMLDivElement> & { [key: `data-${string}`]: unknown };
  /** Ref for the outer shell, e.g. to anchor a popover. */
  rootRef?: React.Ref<HTMLDivElement>;
  /** Extra classes for each part: root, input, adornment. */
  classNames?: ClassNames<'root' | 'input' | 'adornment'>;
}

/**
 * The bare text input under Textfield and friends, with adornment slots. Use
 * it when you want Sparkwire's input behaviour in your own field.
 *
 * The field shell under Textfield and Combobox. One bordered box
 * holds the input and its adornments, lights up on focus, dashes when
 * disabled, and focuses the input when you click anywhere in it. Build your
 * own fields on it; label and help text are up to you (see Field).
 *
 * Style hooks: `.sp-input-base[data-variant][data-size][data-invalid][data-disabled]`,
 * `__input`, `__adornment`. Focus uses `:focus-within`.
 */
export const InputBase = forwardRef<HTMLInputElement, InputBaseProps>(function InputBase(
  { variant = 'outlined', error = false, disabled = false, size = 'medium', startAdornment, endAdornment, rootProps, rootRef, className, classNames, ...props },
  ref,
) {
  const inputRef = useRef<HTMLInputElement>(null);
  return (
    <div
      {...rootProps}
      ref={rootRef}
      className={slot('sp-input-base', classNames, 'root', rootProps?.className)}
      data-variant={variant}
      data-size={size}
      data-tone={error ? 'error' : (rootProps?.['data-tone'] as string | undefined) ?? 'brand'}
      data-invalid={error || undefined}
      data-disabled={disabled || undefined}
      onMouseDown={(e) => {
        rootProps?.onMouseDown?.(e);
        // Clicking the shell's padding focuses the input, like a native field.
        if (e.target === e.currentTarget && !disabled) {
          e.preventDefault();
          inputRef.current?.focus();
        }
      }}
    >
      {startAdornment && <div className={slot('sp-input-base__adornment', classNames, 'adornment')}>{startAdornment}</div>}
      <input
        ref={mergeRefs(inputRef, ref) as React.Ref<HTMLInputElement>}
        className={slot('sp-input-base__input', classNames, 'input', className)}
        disabled={disabled}
        aria-invalid={error || undefined}
        {...props}
      />
      {endAdornment && <div className={slot('sp-input-base__adornment', classNames, 'adornment')}>{endAdornment}</div>}
    </div>
  );
});

export default InputBase;

import React, { useRef } from 'react';
import { mergeRefs, useListBox, useListBoxSection, useOption } from 'react-aria';
import type { AriaListBoxOptions } from 'react-aria';
import { Item, Section, ListState } from 'react-stately';
import type { Node } from '@react-types/shared';
import { cx } from '../internal/cx';

/** A section's items. Some React Aria collections lack getChildren(); every node has childNodes. */
function sectionChildren<T>(collection: object, section: Node<T>): Iterable<Node<T>> {
  const c = collection as { getChildren?: (key: Node<T>["key"]) => Iterable<Node<T>> };
  return typeof c.getChildren === "function" ? c.getChildren(section.key) : section.childNodes;
}


/* ------------------------------------------------------------ items */

export interface ListOption<V extends string | number = string | number> {
  /** Submitted and passed to `onChange`. Numbers come back as numbers. */
  value: V;
  /** Visible text; also used for typeahead and filtering. */
  label: string;
  /** Secondary line under the label. */
  description?: React.ReactNode;
  /** Icon before the label. */
  icon?: React.ReactNode;
  /** Turns the control off: it can't be focused or changed, and it's announced as disabled. */
  disabled?: boolean;
}

export interface ListOptionGroup<O extends ListOption = ListOption> {
  /** Heading for the group. */
  label: string;
  /** The options under this heading. */
  options: O[];
}

export type ListItems<O extends ListOption = ListOption> = Array<O | ListOptionGroup<O>>;

export const isGroup = <O extends ListOption>(o: O | ListOptionGroup<O>): o is ListOptionGroup<O> =>
  Array.isArray((o as ListOptionGroup<O>).options);

/** Every option, groups flattened. */
export const flattenOptions = <O extends ListOption>(items: ListItems<O>): O[] =>
  items.flatMap((o) => (isGroup(o) ? o.options : [o]));

/** Option values are React Aria keys; keep numbers as numbers when reading them back. */
export const findOption = <O extends ListOption>(items: ListItems<O>, key: React.Key | null | undefined) =>
  key == null ? undefined : flattenOptions(items).find((o) => String(o.value) === String(key));

/** Turn plain option objects into a React Aria collection (Items and Sections). */
export function renderListItems<O extends ListOption>(items: ListItems<O>) {
  return items.map((o, i) =>
    isGroup(o) ? (
      <Section key={`group-${i}-${o.label}`} title={o.label}>
        {o.options.map(renderOne)}
      </Section>
    ) : (
      renderOne(o)
    ),
  );
}

function renderOne<O extends ListOption>(o: O) {
  return (
    <Item key={String(o.value)} textValue={o.label}>
      <ListItemContent icon={o.icon} label={o.label} description={o.description} />
    </Item>
  );
}

export interface ListItemContentProps {
  /** Icon before the label. */
  icon?: React.ReactNode;
  /** Main text of the item. */
  label: React.ReactNode;
  /** Secondary line under the label. */
  description?: React.ReactNode;
  /** Shown at the end, e.g. a keyboard shortcut. */
  end?: React.ReactNode;
}

/**
 * The standard layout for an item in a list: an icon, a label, a description
 * and something at the end.
 *
 * The inside of a list row: icon, label, description and an end slot. Shared by options and menu items.
 */
export function ListItemContent({ icon, label, description, end }: ListItemContentProps) {
  return (
    <>
      {icon && (
        <span className="sp-list-item__icon" aria-hidden="true">
          {icon}
        </span>
      )}
      <span className="sp-list-item__text">
        <span className="sp-list-item__label">{label}</span>
        {description && <span className="sp-list-item__description">{description}</span>}
      </span>
      {end && <span className="sp-list-item__end">{end}</span>}
    </>
  );
}

/* ---------------------------------------------------------- listbox */

export interface ListBoxProps<T> extends AriaListBoxOptions<T> {
  /** List state from `useListState`, `useSelectState` or `useComboBoxState`. */
  state: ListState<T>;
  /** Ref to the list element, for scrolling an option into view or measuring. */
  listBoxRef?: React.Ref<HTMLUListElement>;
  /** Extra class names for the outermost element. */
  className?: string;
  /** Extra class for every option row. */
  optionClassName?: string;
  /** Inline style for every option row. */
  optionStyle?: React.CSSProperties;
  /** Shown when there are no options. */
  emptyState?: React.ReactNode;
}

/**
 * An accessible list of options with keyboard navigation and selection, the
 * engine behind Dropdown and Combobox.
 *
 * A list of options to choose from, under Dropdown and Combobox.
 * Each option is a node on a wire: the selected one lights up. Supports
 * groups with headings, icons, descriptions, disabled options and
 * screen-reader announcements.
 *
 * Style hooks: `.sp-listbox`, `.sp-list-section`, `__heading`,
 * `.sp-list-item[data-focused][data-selected][data-disabled]`, `__icon`,
 * `__label`, `__description`, `__check`, `.sp-listbox__empty`.
 */
export function ListBox<T>({ state, listBoxRef, className, optionClassName, optionStyle, emptyState, ...props }: ListBoxProps<T>) {
  const ref = useRef<HTMLUListElement>(null);
  const { listBoxProps } = useListBox(props, state, ref);
  const nodes = Array.from(state.collection);
  return (
    <ul {...listBoxProps} ref={mergeRefs(ref, listBoxRef ?? null) as React.Ref<HTMLUListElement>} className={cx('sp-listbox', className)}>
      {nodes.length === 0 && emptyState ? (
        <li className="sp-listbox__empty" role="presentation">
          {emptyState}
        </li>
      ) : (
        nodes.map((node) =>
          node.type === 'section' ? (
            <ListBoxSection key={node.key} section={node} state={state} optionClassName={optionClassName} optionStyle={optionStyle} />
          ) : (
            <ListBoxOption key={node.key} item={node} state={state} className={optionClassName} style={optionStyle} />
          ),
        )
      )}
    </ul>
  );
}

function ListBoxSection<T>({ section, state, optionClassName, optionStyle }: { section: Node<T>; state: ListState<T>; optionClassName?: string; optionStyle?: React.CSSProperties }) {
  const { itemProps, headingProps, groupProps } = useListBoxSection({ heading: section.rendered, 'aria-label': section['aria-label'] });
  return (
    <li {...itemProps} className="sp-list-section">
      {section.rendered && (
        <span {...headingProps} className="sp-list-section__heading">
          {section.rendered}
        </span>
      )}
      <ul {...groupProps} className="sp-list-section__group">
        {Array.from(sectionChildren(state.collection, section)).map((item) => (
          <ListBoxOption key={item.key} item={item} state={state} className={optionClassName} style={optionStyle} />
        ))}
      </ul>
    </li>
  );
}

function ListBoxOption<T>({ item, state, className, style }: { item: Node<T>; state: ListState<T>; className?: string; style?: React.CSSProperties }) {
  const ref = useRef<HTMLLIElement>(null);
  const { optionProps, isSelected, isFocused, isDisabled } = useOption({ key: item.key }, state, ref);
  return (
    <li
      {...optionProps}
      ref={ref}
      className={cx('sp-list-item', className)}
      style={style}
      data-selected={isSelected || undefined}
      data-focused={isFocused || undefined}
      data-disabled={isDisabled || undefined}
    >
      {item.rendered}
      {isSelected && (
        <svg className="sp-list-item__check" width="16" height="16" viewBox="0 0 16 16" aria-hidden="true">
          <path d="M3 8.5l3 3 7-7" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      )}
    </li>
  );
}

export default ListBox;

import React, { useRef } from 'react';
import { createPortal } from 'react-dom';
import { FocusScope, useModalOverlay } from 'react-aria';
import { useOverlayTriggerState } from 'react-stately';
import { usePortalTheme } from '../internal/usePortalTheme';
import { cx } from '../internal/cx';

export interface OverlayProps {
  /** Whether the overlay is shown. */
  open: boolean;
  /** Called on Escape or (when `dismissable`) a click outside the panel. */
  onClose: () => void;
  /** Close on a click outside the panel. Default `true`. */
  dismissable?: boolean;
  /** Ignore Escape. Default `false`. */
  keyboardDismissDisabled?: boolean;
  /** Class for the full-screen root. */
  className?: string;
  /** Class for the dimmed backdrop. */
  backdropClassName?: string;
  /**
   * Render the panel. Spread `panelProps` on it and attach `panelRef`.
   * Use a component here if you need hooks (e.g. `useDialog`).
   */
  children: (panel: { panelProps: React.HTMLAttributes<HTMLElement>; panelRef: React.RefObject<HTMLDivElement> }) => React.ReactNode;
}

/**
 * The layer behind modals and drawers: a backdrop, focus containment and
 * scroll locking, ready for your own dialogs.
 *
 * The full-screen layer under Modal (and future Drawer and
 * Sheet). Renders in a portal that keeps the current theme, dims the page,
 * traps and restores focus, hides the page from screen readers, blocks
 * scrolling, and closes on Escape or an outside click.
 *
 * Style hooks: `.sp-overlay`, `.sp-overlay__backdrop`.
 */
export function Overlay({ open, ...rest }: OverlayProps) {
  const { anchorRef, themeProps } = usePortalTheme(open);
  const anchor = <span ref={anchorRef} hidden />;
  if (!open || typeof document === 'undefined') return anchor;
  return (
    <>
      {anchor}
      {createPortal(<OverlaySurface {...rest} themeProps={themeProps} />, document.body)}
    </>
  );
}

function OverlaySurface({
  onClose,
  dismissable = true,
  keyboardDismissDisabled = false,
  className,
  backdropClassName,
  children,
  themeProps,
}: Omit<OverlayProps, 'open'> & { themeProps: ReturnType<typeof usePortalTheme>['themeProps'] }) {
  const panelRef = useRef<HTMLDivElement>(null);
  const state = useOverlayTriggerState({ isOpen: true, onOpenChange: (isOpen) => !isOpen && onClose() });
  const { modalProps, underlayProps } = useModalOverlay(
    { isDismissable: dismissable, isKeyboardDismissDisabled: keyboardDismissDisabled },
    state,
    panelRef,
  );
  return (
    <div className={cx('sp-overlay', className)} data-state="open" {...themeProps} {...underlayProps}>
      <div aria-hidden="true" className={cx('sp-overlay__backdrop', backdropClassName)} />
      <FocusScope contain restoreFocus autoFocus>
        {children({ panelProps: modalProps, panelRef })}
      </FocusScope>
    </div>
  );
}

export default Overlay;

import React, { forwardRef, useRef } from 'react';
import { Overlay as AriaOverlay, mergeRefs, usePopover } from 'react-aria';
import { useMessages } from '../internal/messages';
import type { AriaPopoverProps } from 'react-aria';
import type { OverlayTriggerState } from 'react-stately';
import { usePortalTheme } from '../internal/usePortalTheme';
import { cx } from '../internal/cx';

/** Like React Aria's DismissButton (a hidden close button for screen readers), with a translated name. */
function DismissButton({ onDismiss }: { onDismiss: () => void }) {
  const m = useMessages();
  return (
    <button type="button" tabIndex={-1} aria-label={m.dismiss} onClick={onDismiss} className="sp-visually-hidden" style={{ position: 'absolute', width: 1, height: 1, padding: 0, margin: -1, overflow: 'hidden', clip: 'rect(0 0 0 0)', whiteSpace: 'nowrap', border: 0 }} />
  );
}

export interface PopoverProps extends Omit<AriaPopoverProps, 'popoverRef' | 'triggerRef'> {
  /** Open state, from `useOverlayTriggerState` or a component state (select, combobox, menu). */
  state: OverlayTriggerState;
  /** The element the popover is attached to. Its theme is copied to the popover. */
  triggerRef: React.RefObject<Element | null>;
  /** Make the popover at least as wide as the trigger. */
  matchTriggerWidth?: boolean;
  /** Leave focus handling to the content (used by submenus). */
  disableFocusManagement?: boolean;
  /** Extra class names for the outermost element. */
  className?: string;
  /** Inline styles for the outermost element. */
  style?: React.CSSProperties;
  /** The popover's content. */
  children: React.ReactNode;
}

/**
 * A floating panel anchored to a trigger, with focus management and dismissal
 * handled. The building block under Dropdown, Menu and the date pickers.
 *
 * A floating panel attached to a trigger, under Dropdown, Combobox,
 * Menu and DatePicker. Positions itself and flips to stay on screen, renders
 * in a portal that keeps the current theme, closes on outside click and
 * Escape, and has hidden dismiss buttons for screen readers.
 *
 * Style hooks: `.sp-popover[data-placement]`.
 */
export const Popover = forwardRef<HTMLDivElement, PopoverProps>(function Popover(
  { state, triggerRef, matchTriggerWidth, disableFocusManagement, className, style, children, placement = 'bottom start', offset = 6, isNonModal, ...rest },
  ref,
) {
  const popoverRef = useRef<HTMLDivElement>(null);
  const { popoverProps, underlayProps, placement: actual } = usePopover(
    { ...rest, placement, offset, isNonModal, popoverRef, triggerRef: triggerRef as React.RefObject<Element> },
    state,
  );
  const { themeProps } = usePortalTheme(true, triggerRef);
  const width = matchTriggerWidth ? (triggerRef.current as HTMLElement | null)?.offsetWidth : undefined;
  return (
    <AriaOverlay disableFocusManagement={disableFocusManagement}>
      <div {...themeProps} style={{ ...themeProps.style, display: 'contents' }}>
        {!isNonModal && <div {...underlayProps} style={{ position: 'fixed', inset: 0 }} />}
        <div
          {...popoverProps}
          ref={mergeRefs(popoverRef, ref) as React.Ref<HTMLDivElement>}
          className={cx('sp-popover', className)}
          data-placement={actual ?? undefined}
          style={{ ...popoverProps.style, minWidth: width, ...style }}
        >
          {!isNonModal && <DismissButton onDismiss={state.close} />}
          {children}
          <DismissButton onDismiss={state.close} />
        </div>
      </div>
    </AriaOverlay>
  );
});

export default Popover;

/**
 * Spark UI base components: the building blocks under the advanced
 * components. Use them to build your own components that match the rest of
 * the library.
 *
 * Unstable until 1.0: names and props may still change in minor versions.
 */
export { ButtonBase } from './ButtonBase';
export type { ButtonBaseProps } from './ButtonBase';
export { InputBase } from './InputBase';
export type { InputBaseProps } from './InputBase';
export { Popover } from './Popover';
export type { PopoverProps } from './Popover';
export { ListBox, ListItemContent, renderListItems, flattenOptions, findOption, isGroup } from './ListBox';
export type { ListBoxProps, ListItemContentProps, ListOption, ListOptionGroup, ListItems } from './ListBox';
export { Overlay } from './Overlay';
export type { OverlayProps } from './Overlay';
